SELECT 'core-2026-09-v4','wishes','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"wishes","title":"Wishes, regrets and if only","level":"B2","order":44,"summary":"Express a desired change in the present, regret about the past or dissatisfaction with someone’s behaviour.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["An unreal present wish","Regret about the past","A wish for changed behaviour","Ability and wishes"],"rules":[{"title":"An unreal present wish","explanation":"After wish or if only, use a past form to imagine a present situation differently. This is sometimes called unreal past: its form is past, but its reference can be now. With be, were is common for all persons in formal hypothetical uses.","pattern":"I wish I **knew** the answer. / If only I **were** taller.","commonMistakes":["A future hope that may come true normally uses hope, not wish + will in the same pattern."],"examples":["Use a past form for an unreal present wish: “I wish she **prepared** the visitor guide more often.”","Use a past form for an unreal present wish: “I wish she **restored** the old portrait more often.”"],"skill":"form"},{"title":"Regret about the past","explanation":"Use **wish + past perfect** to regret an earlier event or non-event. The past perfect marks the fact that the past cannot now be changed. The wish describes an alternative to it.","pattern":"I wish I **had checked** the time.","commonMistakes":["I wish I checked yesterday does not give the standard past-regret form; use had checked."],"examples":["The task was not done yesterday: “I wish I **had prepared** the visitor guide then.”","The task was not done yesterday: “I wish I **had restored** the old portrait then.”"],"skill":"meaning"},{"title":"A wish for changed behaviour","explanation":"Wish + would often expresses a desire for another person or an external situation to change, especially an irritating repeated behaviour. It normally concerns willingness or behaviour, rather than a simple characteristic.","pattern":"I wish they **would listen**.","commonMistakes":["I wish I would be taller is not the normal way to wish for a different characteristic."],"examples":["You want someone to change an annoying habit: “I wish they would **prepare** the visitor guide without being asked.”","You want someone to change an annoying habit: “I wish they would **restore** the old portrait without being asked.”"],"skill":"contrast"},{"title":"Ability and wishes","explanation":"Wish + could can express a desired ability or opportunity. Compare I wish I could come with I hope I can come: the former suggests a barrier, while the latter leaves the possibility open. If only usually makes the wish more emphatic.","pattern":"If only I **could stay** longer.","commonMistakes":["Choose wish or hope from the speaker’s view of reality, not just from whether the sentence refers to the future."],"examples":["You lack the ability: “If only I could **prepare** the visitor guide by myself.”","You lack the ability: “If only I could **restore** the old portrait by myself.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-wishes"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Express a desired change in the present, regret about the past or dissatisfaction with someone’s behaviour.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"An unreal present wish","explanation":"After wish or if only, use a past form to imagine a present situation differently. This is sometimes called unreal past: its form is past, but its reference can be now. With be, were is common for all persons in formal hypothetical uses.","pattern":"I wish I **knew** the answer. / If only I **were** taller.","commonMistakes":["A future hope that may come true normally uses hope, not wish + will in the same pattern."],"examples":["Use a past form for an unreal present wish: “I wish she **prepared** the visitor guide more often.”","Use a past form for an unreal present wish: “I wish she **restored** the old portrait more often.”"],"skill":"form","id":"wishes-foundation-1","domain":"verbs","referenceIds":["bc-wishes"],"readingVersion":"core-2026-09-v3"},{"title":"Regret about the past","explanation":"Use **wish + past perfect** to regret an earlier event or non-event. The past perfect marks the fact that the past cannot now be changed. The wish describes an alternative to it.","pattern":"I wish I **had checked** the time.","commonMistakes":["I wish I checked yesterday does not give the standard past-regret form; use had checked."],"examples":["The task was not done yesterday: “I wish I **had prepared** the visitor guide then.”","The task was not done yesterday: “I wish I **had restored** the old portrait then.”"],"skill":"meaning","id":"wishes-foundation-2","domain":"verbs","referenceIds":["bc-wishes"],"readingVersion":"core-2026-09-v3"},{"title":"A wish for changed behaviour","explanation":"Wish + would often expresses a desire for another person or an external situation to change, especially an irritating repeated behaviour. It normally concerns willingness or behaviour, rather than a simple characteristic.","pattern":"I wish they **would listen**.","commonMistakes":["I wish I would be taller is not the normal way to wish for a different characteristic."],"examples":["You want someone to change an annoying habit: “I wish they would **prepare** the visitor guide without being asked.”","You want someone to change an annoying habit: “I wish they would **restore** the old portrait without being asked.”"],"skill":"contrast","id":"wishes-foundation-3","domain":"verbs","referenceIds":["bc-wishes"],"readingVersion":"core-2026-09-v3"},{"title":"Ability and wishes","explanation":"Wish + could can express a desired ability or opportunity. Compare I wish I could come with I hope I can come: the former suggests a barrier, while the latter leaves the possibility open. If only usually makes the wish more emphatic.","pattern":"If only I **could stay** longer.","commonMistakes":["Choose wish or hope from the speaker’s view of reality, not just from whether the sentence refers to the future."],"examples":["You lack the ability: “If only I could **prepare** the visitor guide by myself.”","You lack the ability: “If only I could **restore** the old portrait by myself.”"],"skill":"application","id":"wishes-foundation-4","domain":"verbs","referenceIds":["bc-wishes"],"readingVersion":"core-2026-09-v3"}],"recap":["I wish I **knew** the answer. / If only I **were** taller.","I wish I **had checked** the time.","I wish they **would listen**.","If only I **could stay** longer."],"readingVersion":"core-2026-09-v4"},"stage":"4 · Connecting meanings","prerequisites":["third-mixed-conditionals"],"readingReferenceIds":["bc-wishes"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='wishes'
